def policy(board: list[list[int]]) -> tuple[int, int]:
    """
    Battleship policy using target mode and hunt mode.
    Target mode: Prioritize extending lines of consecutive hits.
    Hunt mode: Use probability density based on possible ship placements.
    """
    ROWS, COLS = 10, 10
    SHIPS = [5, 4, 3, 3, 2]

    def in_bounds(r, c):
        return 0 <= r < ROWS and 0 <= c < COLS

    # ===== TARGET MODE =====
    # Find the best cell to shoot adjacent to existing hits
    best_target = None
    best_priority = -1

    for r in range(ROWS):
        for c in range(COLS):
            if board[r][c] != 1:
                continue

            # Check each direction from this hit
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc

                # Skip if out of bounds or already explored
                if not in_bounds(nr, nc) or board[nr][nc] != 0:
                    continue

                # Count consecutive hits in the opposite direction
                line_len = 1
                br, bc = r - dr, c - dc
                while in_bounds(br, bc) and board[br][bc] == 1:
                    line_len += 1
                    br, bc = br - dr, bc - dc

                # Update best target if this has higher priority
                if line_len > best_priority:
                    best_priority = line_len
                    best_target = (nr, nc)

    if best_target:
        return best_target

    # ===== HUNT MODE =====
    # Calculate probability density for each unknown cell
    prob = [[0] * COLS for _ in range(ROWS)]

    for ship_len in SHIPS:
        # Check all horizontal placements
        for r in range(ROWS):
            for c in range(COLS - ship_len + 1):
                if all(board[r][c + i] == 0 for i in range(ship_len)):
                    for i in range(ship_len):
                        prob[r][c + i] += 1

        # Check all vertical placements
        for r in range(ROWS - ship_len + 1):
            for c in range(COLS):
                if all(board[r + i][c] == 0 for i in range(ship_len)):
                    for i in range(ship_len):
                        prob[r + i][c] += 1

    # Find cell with highest probability
    best_r, best_c = 0, 0
    best_prob = -1
    for r in range(ROWS):
        for c in range(COLS):
            if board[r][c] == 0 and prob[r][c] > best_prob:
                best_prob = prob[r][c]
                best_r, best_c = r, c

    return (best_r, best_c)
